COMMENT ON COLUMN cardiac_stress_test_result_grade_rule.id IS
    'Primary key UUID, auto-generated.';
COMMENT ON COLUMN cardiac_stress_test_result_grade_rule.created_at IS
    'Timestamp when this row was created.';
COMMENT ON COLUMN cardiac_stress_test_result_grade_rule.updated_at IS
    'Timestamp when the record was updated most-recently.';
COMMENT ON COLUMN cardiac_stress_test_result_grade_rule.deleted_at IS
    'Timestamp when the record was deleted a.k.a. soft-removed.';
COMMENT ON COLUMN cardiac_stress_test_result_grade_rule.cardiac_stress_test_result_grade_id IS
    'Foreign key to the parent grade.';
COMMENT ON COLUMN cardiac_stress_test_result_grade_rule.rule_id IS
